const fs = require('fs');
const RAIZ = 'C:\\Users\\usuario\\Desktop\\Projeto-professor-William';
const ALERTAS = RAIZ + '\\auditoria\\alertas-automaticos.md';

const hoje = new Date();
const pad = n => String(n).padStart(2, '0');
const hojeStr = `${hoje.getFullYear()}-${pad(hoje.getMonth()+1)}-${pad(hoje.getDate())}`;

const candidatos = [
  { label: 'Digest de pesquisa', path: `${RAIZ}\\pesquisa-diaria\\${hojeStr}.md` },
  { label: 'Ata da reunião', path: `${RAIZ}\\auditoria\\${hojeStr}-reuniao.md` },
  { label: 'Auditoria diária', path: `${RAIZ}\\auditoria\\${hojeStr}.md` }
];

const quebrados = [];
const checados = [];
for (const c of candidatos) {
  if (!fs.existsSync(c.path)) continue;
  const buf = fs.readFileSync(c.path);
  checados.push(c.label);
  // BOM UTF-16LE = 0xFF 0xFE (Armadilha 31: '*>' do PowerShell grava assim por padrao)
  if (buf.length >= 2 && buf[0] === 0xFF && buf[1] === 0xFE) {
    quebrados.push(c.label);
  }
  // BOM UTF-16BE, menos comum mas tambem quebra
  if (buf.length >= 2 && buf[0] === 0xFE && buf[1] === 0xFF) {
    quebrados.push(c.label + ' (UTF-16BE)');
  }
}

const agora = new Date();
const horaStr = `${pad(agora.getHours())}:${pad(agora.getMinutes())}`;
let bloco = `\n## ${hojeStr} ${horaStr} — n8n (automático, Encoding Quebrado — Armadilha 31)\n\n`;

if (checados.length === 0) {
  bloco += 'Nenhum dos arquivos do dia existe ainda pra checar.\n';
} else if (quebrados.length === 0) {
  bloco += `${checados.length} arquivo(s) checado(s) (${checados.join(', ')}) — nenhum com BOM UTF-16, encoding OK.\n`;
} else {
  bloco += `ENCODING QUEBRADO em ${quebrados.length} arquivo(s): ${quebrados.join(', ')}. Isso é a Armadilha 31 (PowerShell '*>' grava UTF-16LE) acontecendo de novo — reescrever com Out-File -Encoding utf8 ou equivalente.\n`;
}

if (!fs.existsSync(ALERTAS)) {
  fs.writeFileSync(ALERTAS, '# Alertas automáticos — n8n\n\n' + bloco, 'utf8');
} else {
  fs.appendFileSync(ALERTAS, bloco, 'utf8');
}

return [{ json: { checados, quebrados } }];
